import json
from opentrons import protocol_api, types

metadata = {
    "protocolName": "Illumina DNA Prep 48x v8 December 4th ",
    "author": "Opentrons QA",
    "description": "This is a FLEX protocol for Illumina DNA Prep for up to 48 samples. This protocol's workflow starts with the Tagmentation of input DNA and proceeds to Bead Cleanup of the final libraries. A higher throughput version, that still uses Multichannels, can be found here: Illumina DNA Prep 96x\n\nA lower throughput 24x version of this protocol for the OT2 can be found here. Illumina DNA Prep 24x for OT2\n\nDepending on the number of samples selected the protocol can be either walkaway or require user intervention to reset tipracks.\nIllumina DNA Prep Reference Guide",
    "created": "2024-12-03T19:58:04.829Z",
    "internalAppBuildDate": "Fri, 23 Jan 2026 20:05:49 GMT",
    "lastModified": "2026-01-26T19:57:36.801Z",
    "protocolDesigner": "8.8.0-alpha.7",
    "source": "Protocol Designer",
}

requirements = {"robotType": "Flex", "apiLevel": "2.27"}

def run(protocol: protocol_api.ProtocolContext) -> None:
    # Load Modules:
    thermocycler_module_1 = protocol.load_module("thermocyclerModuleV2", "B1")
    temperature_module_1 = protocol.load_module("temperatureModuleV2", "C1")
    heater_shaker_module_1 = protocol.load_module("heaterShakerModuleV1", "D1")
    magnetic_block_1 = protocol.load_module("magneticBlockV1", "D2")

    # Load Adapters:
    aluminum_block_1 = temperature_module_1.load_adapter(
        "opentrons_96_well_aluminum_block",
        namespace="opentrons",
        version=1,
    )
    adapter_1 = heater_shaker_module_1.load_adapter(
        "opentrons_96_pcr_adapter",
        namespace="opentrons",
        version=1,
    )

    # Load Labware:
    tip_rack_1 = protocol.load_labware(
        "opentrons_flex_96_tiprack_50ul",
        location="C3",
        namespace="opentrons",
        version=1,
    )
    tip_rack_2 = protocol.load_labware(
        "opentrons_flex_96_filtertiprack_200ul",
        location="A3",
        label="Opentrons Flex 96 Filter Tip Rack 200 µL (1)",
        namespace="opentrons",
        version=1,
    )
    tip_rack_3 = protocol.load_labware(
        "opentrons_flex_96_filtertiprack_200ul",
        location="B3",
        label="Opentrons Flex 96 Filter Tip Rack 200 µL (2)",
        namespace="opentrons",
        version=1,
    )
    tip_rack_4 = protocol.load_labware(
        "opentrons_flex_96_filtertiprack_200ul",
        location="A2",
        label="Opentrons Flex 96 Filter Tip Rack 200 µL (3)",
        namespace="opentrons",
        version=1,
    )
    tip_rack_5 = protocol.load_labware(
        "opentrons_flex_96_filtertiprack_200ul",
        location="B2",
        label="Opentrons Flex 96 Filter Tip Rack 200 µL (4)",
        namespace="opentrons",
        version=1,
    )
    well_plate_1 = aluminum_block_1.load_labware(
        "opentrons_96_wellplate_200ul_pcr_full_skirt",
        label="Reagent Plate",
        namespace="opentrons",
        version=4,
    )
    well_plate_2 = adapter_1.load_labware(
        "opentrons_96_wellplate_200ul_pcr_full_skirt",
        label="Sample Plate 1",
        namespace="opentrons",
        version=4,
    )
    well_plate_3 = magnetic_block_1.load_labware(
        "nest_96_wellplate_2ml_deep",
        label="NEST 96 Deep Well Plate 2mL",
        namespace="opentrons",
        version=5,
    )
    reservoir_1 = protocol.load_labware(
        "nest_12_reservoir_15ml",
        location="C2",
        namespace="opentrons",
        version=3,
    )
    tip_rack_6 = protocol.load_labware(
        "opentrons_flex_96_tiprack_50ul",
        location="D4",
        label="Opentrons Flex 96 Tip Rack 50 µL (1)",
        namespace="opentrons",
        version=1,
    )
    tip_rack_7 = protocol.load_labware(
        "opentrons_flex_96_filtertiprack_200ul",
        location=protocol_api.OFF_DECK,
        label="Opentrons Flex 96 Filter Tip Rack 200 µL (5)",
        namespace="opentrons",
        version=1,
    )
    tip_rack_8 = protocol.load_labware(
        "opentrons_flex_96_tiprack_50ul",
        location=protocol_api.OFF_DECK,
        label="Opentrons Flex 96 Tip Rack 50 µL (2)",
        namespace="opentrons",
        version=1,
    )

    # Load Pipettes:
    pipette_left = protocol.load_instrument("flex_8channel_1000", "left")
    pipette_right = protocol.load_instrument("flex_8channel_50", "right")

    # Load Waste Chute:
    waste_chute = protocol.load_waste_chute()

    # Define Liquids:
    liquid_1 = protocol.define_liquid(
        "Barcodes",
        display_color="#7eff42ff",
    )
    liquid_2 = protocol.define_liquid(
        "Tagmix",
        display_color="#ffd600",
    )
    liquid_3 = protocol.define_liquid(
        "H20",
        display_color="#176eefff",
    )
    liquid_4 = protocol.define_liquid(
        "TAGSTOP",
        display_color="#ff4f4fff",
    )
    liquid_5 = protocol.define_liquid(
        "EtOH",
        display_color="#915656ff",
    )
    liquid_6 = protocol.define_liquid(
        "RSB",
        description="Resuspension buffer",
        display_color="#3beddaff",
    )
    liquid_7 = protocol.define_liquid(
        "EtOH 80%",
        display_color="#56b89dff",
    )
    liquid_8 = protocol.define_liquid(
        "TWG",
        description="Tagmentation Wash Buffer ",
        display_color="#f6c158ff",
    )
    liquid_9 = protocol.define_liquid(
        "Liquid_trash_well",
        display_color="#747474ff",
    )
    liquid_10 = protocol.define_liquid(
        "Sample ",
        display_color="#1900ffff",
    )
    liquid_11 = protocol.define_liquid(
        "Placeholder_Sample",
        display_color="#cdd7d3eb",
    )
    liquid_12 = protocol.define_liquid(
        "Final_Sample ",
        display_color="#d0ccc7ff",
    )

    # Load Liquids:
    well_plate_1.load_liquid(
        wells=[
            "A7", "B7", "C7", "D7", "E7", "F7", "G7", "H7",
            "A8", "B8", "C8", "D8", "E8", "F8", "G8", "H8",
            "A9", "B9", "C9", "D9", "E9", "F9", "G9", "H9"
        ],
        liquid=liquid_1,
        volume=5,
    )
    well_plate_1.load_liquid(
        wells=[
            "A1", "B1", "C1", "D1", "E1", "F1", "G1", "H1"
        ],
        liquid=liquid_2,
        volume=80,
    )
    well_plate_1.load_liquid(
        wells=[
            "B2", "C2", "D2", "E2", "F2", "G2", "H2", "A2"
        ],
        liquid=liquid_3,
        volume=120,
    )
    reservoir_1.load_liquid(
        wells=["A1"],
        liquid=liquid_5,
        volume=135,
    )
    reservoir_1.load_liquid(
        wells=["A2"],
        liquid=liquid_6,
        volume=96,
    )
    reservoir_1.load_liquid(
        wells=["A4"],
        liquid=liquid_7,
        volume=900,
    )
    reservoir_1.load_liquid(
        wells=["A7"],
        liquid=liquid_8,
        volume=2700,
    )
    reservoir_1.load_liquid(
        wells=["A10", "A11", "A12"],
        liquid=liquid_9,
        volume=1,
    )
    well_plate_2.load_liquid(
        wells=[
            "A1", "B1", "C1", "D1", "E1", "F1", "G1", "H1",
            "A2", "B2", "C2", "D2", "E2", "F2", "G2", "H2",
            "A3", "B3", "C3", "D3", "E3", "F3", "G3", "H3"
        ],
        liquid=liquid_10,
        volume=40,
    )
    well_plate_2.load_liquid(
        wells=[
            "A5", "B5", "C5", "D5", "E5", "F5", "G5", "H5",
            "A6", "B6", "C6", "D6", "E6", "F6", "G6", "H6",
            "A7", "B7", "C7", "D7", "E7", "F7", "G7", "H7"
        ],
        liquid=liquid_11,
        volume=1,
    )
    well_plate_2.load_liquid(
        wells=[
            "A9", "B9", "C9", "D9", "E9", "F9", "G9", "H9",
            "A10", "B10", "C10", "D10", "E10", "F10", "G10", "H10",
            "A11", "B11", "C11", "D11", "E11", "F11", "G11", "H11"
        ],
        liquid=liquid_12,
        volume=1,
    )

    # PROTOCOL STEPS



